import 'server-only';
import type { Currency, Market } from '@cmobeat/config';
import { adminDb, listings, mandates } from '@cmobeat/db';
import { and, eq, inArray, isNotNull, ne, sql } from 'drizzle-orm';

/**
 * Comp benchmark (spec 5.3.2). Computed from data, never generated by a model.
 *
 * Method: midpoint of each advertised range on CMO Beat listings (live and expired) with the same
 * level, market, currency and pay basis. Fewer than 5 comparable listings → "not enough data".
 *
 * It reads expired listings, which employers cannot see row by row, so it runs on the system
 * connection and returns aggregates only — never a company, a listing or a single figure.
 */
export const MIN_SAMPLE = 5;

export interface CompBenchmark {
  enough: boolean;
  n: number;
  p25: number | null;
  median: number | null;
  p75: number | null;
  currency: Currency;
  basis: 'annual' | 'monthly_retainer';
  level: string;
  market: Market;
  /** True when any listing in the sample is sample data. */
  sample: boolean;
  method: string;
  asOf: string;
}

export const benchmarkMethod =
  'Midpoint of advertised comp ranges on CMO Beat listings (live and expired) at the same level, market, currency and pay basis.';

/** Percentile with linear interpolation (same as Postgres percentile_cont). */
export function percentile(sorted: number[], p: number): number {
  if (!sorted.length) return NaN;
  const idx = (sorted.length - 1) * p;
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  return Math.round(sorted[lo]! + (sorted[hi]! - sorted[lo]!) * (idx - lo));
}

export async function computeBenchmark(input: {
  level: string;
  market: Market;
  currency: Currency;
  basis: 'annual' | 'monthly_retainer';
  excludeMandateId?: string;
  now?: Date;
}): Promise<CompBenchmark> {
  const rows = await adminDb()
    .select({
      mid: sql<number>`((${mandates.compMin} + ${mandates.compMax}) / 2.0)::float`,
      sample: mandates.isSample,
    })
    .from(listings)
    .innerJoin(mandates, eq(mandates.id, listings.mandateId))
    .where(
      and(
        inArray(listings.status, ['live', 'expired']),
        sql`${mandates.level}::text = ${input.level}`,
        eq(mandates.market, input.market),
        eq(mandates.currency, input.currency),
        eq(mandates.compBasis, input.basis),
        isNotNull(mandates.compMin),
        isNotNull(mandates.compMax),
        input.excludeMandateId ? ne(mandates.id, input.excludeMandateId) : undefined,
      ),
    );
  const mids = rows.map((r) => Number(r.mid)).sort((a, b) => a - b);
  const enough = mids.length >= MIN_SAMPLE;
  return {
    enough,
    n: mids.length,
    p25: enough ? percentile(mids, 0.25) : null,
    median: enough ? percentile(mids, 0.5) : null,
    p75: enough ? percentile(mids, 0.75) : null,
    currency: input.currency,
    basis: input.basis,
    level: input.level,
    market: input.market,
    sample: rows.some((r) => r.sample),
    method: benchmarkMethod,
    asOf: (input.now ?? new Date()).toISOString().slice(0, 10),
  };
}
